def lookup_insight(slug: str) -> dict[str, Any] | None:
    for item in INSIGHT_TEMPLATES:
        if item.slug == slug:
            return item.as_dict()
    return None

def list_insights(category: str | None = None, risk_level: str | None = None) -> list[dict[str, Any]]:
    items = INSIGHT_TEMPLATES
    if category:
        items = [item for item in items if item.category == category]
    if risk_level:
        items = [item for item in items if item.risk_level == risk_level]
    return [item.as_dict() for item in items]

def sample_insight_report(limit: int = 10) -> dict[str, Any]:
    selected = INSIGHT_TEMPLATES[:limit]
    return {"report_title": "Atlas Insight Template Summary", "limit": limit, "items": [item.as_dict() for item in selected]}

def grouped_insight_summary() -> dict[str, Any]:
    groups: dict[str, dict[str, Any]] = {}
    for item in INSIGHT_TEMPLATES:
        group = groups.setdefault(item.category, {"count": 0, "priority_total": 0, "tags": set()})
        group["count"] += 1
        group["priority_total"] += item.priority
        group["tags"].update(item.tags)
    return {cat: {"count": data["count"], "average_priority": round(data["priority_total"] / max(data["count"], 1), 2), "tags": sorted(data["tags"])} for cat, data in groups.items()}